# ABOUTME: Sea of Nodes IR node representation for Chalk compiler
# ABOUTME: Represents a single node in the IR graph with operation type, inputs, and attributes
use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all);
use utf8;

class Chalk::IR::Node {
    field $id         :param :reader;
    field $op         :param :reader;
    field $inputs     :param :reader;
    field $attributes :param :reader;

    method to_hash() {
        return {
            id         => $id,
            op         => $op,
            inputs     => $inputs,
            attributes => $attributes,
        };
    }

    method peephole($graph) {
        # Peephole optimization for constant folding
        # Check if this is an arithmetic operation with constant operands
        if ($op eq 'Add' || $op eq 'Multiply' || $op eq 'Subtract' || $op eq 'Divide') {
            my $left  = $attributes->{left};
            my $right = $attributes->{right};

            # Both operands must be constants for folding
            my $left_is_const = 0;
            if (defined($left)) {
                if ($left->{op} eq 'Constant') {
                    $left_is_const = 1;
                }
            }
            my $right_is_const = 0;
            if (defined($right)) {
                if ($right->{op} eq 'Constant') {
                    $right_is_const = 1;
                }
            }
            if ($left_is_const) {
                if ($right_is_const) {
                    my $left_val  = $left->{value};
                    my $right_val = $right->{value};
                    my $result;

                # Compute the result based on operation
                if ($op eq 'Add') {
                    $result = $left_val + $right_val;
                }
                elsif ($op eq 'Multiply') {
                    $result = $left_val * $right_val;
                }
                elsif ($op eq 'Subtract') {
                    $result = $left_val - $right_val;
                }
                elsif ($op eq 'Divide') {
                    # Avoid division by zero
                    return $self if $right_val == 0;
                    $result = int($left_val / $right_val);  # Integer division
                }

                # Return a new Constant node with the folded result
                return Chalk::IR::Node->new(
                    id         => $id,  # Reuse the same ID
                    op         => 'Constant',
                    inputs     => $inputs,
                    attributes => {
                        value => $result,
                        type  => 'Int',
                    }
                );
                }
            }
        }

        # Check if this is a comparison operation with constant operands
        if ($op eq 'GT' || $op eq 'LT' || $op eq 'EQ' || $op eq 'NE' || $op eq 'LE' || $op eq 'GE') {
            my $left  = $attributes->{left};
            my $right = $attributes->{right};

            # Both operands must be constants for folding
            my $left_is_const = 0;
            if (defined($left)) {
                if ($left->{op} eq 'Constant') {
                    $left_is_const = 1;
                }
            }
            my $right_is_const = 0;
            if (defined($right)) {
                if ($right->{op} eq 'Constant') {
                    $right_is_const = 1;
                }
            }
            if ($left_is_const) {
                if ($right_is_const) {
                    my $left_val  = $left->{value};
                    my $right_val = $right->{value};
                    my $result;

                    # Compute the result based on comparison operation
                    if ($op eq 'GT') {
                        $result = $left_val > $right_val ? 1 : 0;
                    }
                    elsif ($op eq 'LT') {
                        $result = $left_val < $right_val ? 1 : 0;
                    }
                    elsif ($op eq 'EQ') {
                        $result = $left_val == $right_val ? 1 : 0;
                    }
                    elsif ($op eq 'NE') {
                        $result = $left_val != $right_val ? 1 : 0;
                    }
                    elsif ($op eq 'LE') {
                        $result = $left_val <= $right_val ? 1 : 0;
                    }
                    elsif ($op eq 'GE') {
                        $result = $left_val >= $right_val ? 1 : 0;
                    }

                    # Return a new Constant node with the folded result (1 or 0)
                    return Chalk::IR::Node->new(
                        id         => $id,  # Reuse the same ID
                        op         => 'Constant',
                        inputs     => $inputs,
                        attributes => {
                            value => $result,
                            type  => 'Int',
                        }
                    );
                }
            }
        }

        # Load nodes can be optimized if they reference a Store with a constant value
        if ($op eq 'Load') {
            my $store_id = $attributes->{store_id};
            if (defined($store_id)) {
                my $store_node = $graph->get_node($store_id);
                my $is_store = 0;
                if (defined($store_node)) {
                    if ($store_node->op eq 'Store') {
                        $is_store = 1;
                    }
                }
                if ($is_store) {
                    my $value_ref = $store_node->attributes->{value};
                    my $is_const = 0;
                    if (defined($value_ref)) {
                        if ($value_ref->{op} eq 'Constant') {
                            $is_const = 1;
                        }
                    }
                    # If the stored value is a constant, fold the Load to that constant
                    if ($is_const) {
                        return Chalk::IR::Node->new(
                            id         => $id,
                            op         => 'Constant',
                            inputs     => $inputs,
                            attributes => {
                                value => $value_ref->{value},
                                type  => $value_ref->{type},
                            }
                        );
                    }
                }
            }
        }

        # Chapter 6: Proj node optimization for constant If conditions
        if ($op eq 'Proj') {
            # Check if this Proj is from an If node
            if (scalar(@$inputs) > 0) {
                my $parent_id = $inputs->[0];
                my $parent = $graph->get_node($parent_id);
                if (defined($parent) && $parent->op eq 'If') {
                    # Get the If node's condition
                    my $condition_attr = $parent->attributes->{condition};
                    if (defined($condition_attr) && $condition_attr->{op} eq 'Constant') {
                        my $cond_value = $condition_attr->{value};
                        my $proj_index = $attributes->{index};

                        # If condition is true (non-zero), index 0 is live, index 1 is dead
                        # If condition is false (zero), index 1 is live, index 0 is dead
                        my $is_live = ($cond_value) ? ($proj_index == 0) : ($proj_index == 1);

                        if ($is_live) {
                            # Live branch: pass through the If node's control input
                            if (scalar(@{$parent->inputs}) > 0) {
                                my $ctrl_id = $parent->inputs->[0];
                                my $ctrl_node = $graph->get_node($ctrl_id);
                                if (defined($ctrl_node)) {
                                    return $ctrl_node;
                                }
                            }
                        } else {
                            # Dead branch: return ~Ctrl constant
                            return Chalk::IR::Node->new(
                                id         => $id,
                                op         => 'Constant',
                                inputs     => [],
                                attributes => {
                                    value => '~Ctrl',
                                    type  => 'Control',
                                }
                            );
                        }
                    }
                }
            }
        }

        # Chapter 6: Region node collapse when only one input is live
        if ($op eq 'Region') {
            my @live_inputs;
            for my $input_id (@$inputs) {
                my $input_node = $graph->get_node($input_id);
                if (defined($input_node)) {
                    # Check if input is dead control (~Ctrl)
                    if ($input_node->op eq 'Constant' &&
                        defined($input_node->attributes->{value}) &&
                        $input_node->attributes->{value} eq '~Ctrl') {
                        # Skip dead input
                        next;
                    }
                    push @live_inputs, $input_id;
                }
            }

            # If only one live input, collapse to that input
            if (scalar(@live_inputs) == 1) {
                my $live_id = $live_inputs[0];
                my $live_node = $graph->get_node($live_id);
                if (defined($live_node)) {
                    return $live_node;
                }
            }
        }

        # Chapter 6: Phi node simplification when one or more inputs are from dead control
        if ($op eq 'Phi') {
            my $region_id = $attributes->{region_id};
            if (defined($region_id)) {
                my $region = $graph->get_node($region_id);
                if (defined($region) && $region->op eq 'Region') {
                    my @region_inputs = @{$region->inputs};
                    my $alternatives = $attributes->{alternatives} || [];

                    # Find live alternatives (where corresponding Region input is not ~Ctrl)
                    my @live_values;
                    for my $i (0 .. $#region_inputs) {
                        my $ctrl_id = $region_inputs[$i];
                        my $ctrl_node = $graph->get_node($ctrl_id);

                        # Check if this control input is dead
                        my $is_dead = 0;
                        if (defined($ctrl_node)) {
                            if ($ctrl_node->op eq 'Constant' &&
                                defined($ctrl_node->attributes->{value}) &&
                                $ctrl_node->attributes->{value} eq '~Ctrl') {
                                $is_dead = 1;
                            }
                        }

                        # If control is live, keep this alternative
                        if (!$is_dead && $i < scalar(@$alternatives)) {
                            push @live_values, $alternatives->[$i];
                        }
                    }

                    # If only one live value, replace Phi with that value
                    if (scalar(@live_values) == 1) {
                        my $value_ref = $live_values[0];
                        if ($value_ref->{op} eq 'NodeRef') {
                            my $value_node = $graph->get_node($value_ref->{node_id});
                            if (defined($value_node)) {
                                return $value_node;
                            }
                        }
                    }
                }
            }
        }

        # No optimization possible, return self
        return $self;
    }
}

1;

content.content:
     1→# ABOUTME: Validator for Sea of Nodes IR graphs checking SSA properties, CFG structure, dominance, and phi nodes
     2→# ABOUTME: Provides comprehensive validation infrastructure to catch IR construction errors before compilation
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Validator {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→
    11→    # Main validation entry point - runs all validators
    12→    method validate_all($graph) {
    13→        my @all_errors = ();
    14→
    15→        # Run each validator and collect errors
    16→        push @all_errors, $self->validate_cfg($graph);
    17→        push @all_errors, $self->validate_single_assignment($graph);
    18→        push @all_errors, $self->validate_dominance($graph);
    19→        push @all_errors, $self->validate_phi_placement($graph);
    20→
    21→        my $success = scalar(@all_errors) == 0 ? 1 : 0;
    22→        return ($success, \@all_errors);
    23→    }
    24→
    25→    # Validate Control Flow Graph structure
    26→    method validate_cfg($graph) {
    27→        my @errors = ();
    28→
    29→        # Check: Single Start node exists
    30→        my $start_count = 0;
    31→        my $start_id = undef;
    32→        my $nodes = $graph->nodes;
    33→
    34→        for my $node_id (keys $nodes->%*) {
    35→            my $node = $nodes->{$node_id};
    36→            if ($node->op eq 'Start') {
    37→                $start_count++;
    38→                $start_id = $node_id;
    39→            }
    40→        }
    41→
    42→        if ($start_count == 0) {
    43→            push @errors, "CFG validation failed: No Start node found in graph";
    44→        }
    45→        elsif ($start_count > 1) {
    46→            push @errors, "CFG validation failed: Multiple Start nodes found ($start_count), expected exactly 1";
    47→        }
    48→
    49→        # Check: At least one Return node exists
    50→        my $return_count = 0;
    51→        for my $node_id (keys $nodes->%*) {
    52→            my $node = $nodes->{$node_id};
    53→            if ($node->op eq 'Return') {
    54→                $return_count++;
    55→            }
    56→        }
    57→
    58→        if ($return_count == 0) {
    59→            push @errors, "CFG validation failed: No Return node found in graph";
    60→        }
    61→
    62→        # Check: All nodes reachable from Start (BFS traversal)
    63→        if (defined($start_id)) {
    64→            my %reachable = ();
    65→            my @queue = ($start_id);
    66→            $reachable{$start_id} = 1;
    67→
    68→            while (scalar(@queue) > 0) {
    69→                my $current_id = shift @queue;
    70→                my $current_node = $nodes->{$current_id};
    71→
    72→                # Follow all outgoing edges (inputs reference other nodes)
    73→                # Note: In Sea of Nodes, inputs point TO this node FROM others,
    74→                # so we need to find nodes that reference this one
    75→                for my $other_id (keys $nodes->%*) {
    76→                    next if exists($reachable{$other_id});
    77→                    my $other_node = $nodes->{$other_id};
    78→
    79→                    # Check if other_node references current_node
    80→                    for my $input_id ($other_node->inputs->@*) {
    81→                        if ($input_id eq $current_id) {
    82→                            $reachable{$other_id} = 1;
    83→                            push @queue, $other_id;
    84→                            last;
    85→                        }
    86→                    }
    87→                }
    88→            }
    89→
    90→            # Report unreachable nodes (except Constants which are data-only)
    91→            for my $node_id (keys $nodes->%*) {
    92→                if (not(exists($reachable{$node_id}))) {
    93→                    my $node = $nodes->{$node_id};
    94→                    # Constants are data-only nodes and don't need control flow reachability
    95→                    if ($node->op ne 'Constant') {
    96→                        push @errors, "CFG validation failed: Node $node_id is not reachable from Start node";
    97→                    }
    98→                }
    99→            }
   100→        }
   101→
   102→        return @errors;
   103→    }
   104→
   105→    # Validate SSA single assignment property
   106→    method validate_single_assignment($graph) {
   107→        my @errors = ();
   108→        my %assignments = ();  # variable_name => [node_ids]
   109→
   110→        my $nodes = $graph->nodes;
   111→
   112→        # Collect all Store nodes (variable assignments)
   113→        for my $node_id (keys $nodes->%*) {
   114→            my $node = $nodes->{$node_id};
   115→            if ($node->op eq 'Store') {
   116→                my $var_name = $node->attributes->{variable};
   117→                if (defined($var_name)) {
   118→                    $assignments{$var_name} //= [];
   119→                    push $assignments{$var_name}->@*, $node_id;
   120→                }
   121→            }
   122→        }
   123→
   124→        # Check for multiple assignments to same variable
   125→        for my $var_name (keys %assignments) {
   126→            my $assign_list = $assignments{$var_name};
   127→            if (scalar($assign_list->@*) > 1) {
   128→                my $node_list = join(', ', $assign_list->@*);
   129→                push @errors, "SSA violation: Variable $var_name is assigned more than once (in nodes: $node_list)";
   130→            }
   131→        }
   132→
   133→        return @errors;
   134→    }
   135→
   136→    # Compute dominance tree using Cooper/Harvey/Kennedy algorithm
   137→    method compute_dominance_tree($graph) {
   138→        my $nodes = $graph->nodes;
   139→        my %dom = ();  # node_id => immediate_dominator_id
   140→
   141→        # Find Start node
   142→        my $start_id = undef;
   143→        for my $node_id (keys $nodes->%*) {
   144→            my $node = $nodes->{$node_id};
   145→            if ($node->op eq 'Start') {
   146→                $start_id = $node_id;
   147→                last;
   148→            }
   149→        }
   150→
   151→        return \%dom unless defined($start_id);
   152→
   153→        # Build reverse graph (predecessors)
   154→        my %preds = ();  # node_id => [predecessor_ids]
   155→        for my $node_id (keys $nodes->%*) {
   156→            $preds{$node_id} = [];
   157→        }
   158→
   159→        for my $node_id (keys $nodes->%*) {
   160→            my $node = $nodes->{$node_id};
   161→            for my $input_id ($node->inputs->@*) {
   162→                if (exists($nodes->{$input_id})) {
   163→                    push $preds{$node_id}->@*, $input_id;
   164→                }
   165→            }
   166→        }
   167→
   168→        # Initialize: Start dominates itself
   169→        $dom{$start_id} = $start_id;
   170→
   171→        # Iterative dataflow until convergence
   172→        my $changed = 1;
   173→        my $max_iterations = scalar(keys $nodes->%*) * 2;
   174→        my $iterations = 0;
   175→
   176→        while ($changed) {
   177→            if ($iterations > $max_iterations) {
   178→                last;
   179→            }
   180→            $changed = 0;
   181→            $iterations++;
   182→
   183→            for my $node_id (keys $nodes->%*) {
   184→                next if $node_id eq $start_id;
   185→
   186→                my @pred_list = $preds{$node_id}->@*;
   187→                next if scalar(@pred_list) == 0;
   188→
   189→                # Find first processed predecessor
   190→                my $new_idom = undef;
   191→                for my $pred_id (@pred_list) {
   192→                    if (exists($dom{$pred_id})) {
   193→                        $new_idom = $pred_id;
   194→                        last;
   195→                    }
   196→                }
   197→
   198→                next unless defined($new_idom);
   199→
   200→                # Intersect with all other predecessors
   201→                for my $pred_id (@pred_list) {
   202→                    next if $pred_id eq $new_idom;
   203→                    next unless exists($dom{$pred_id});
   204→
   205→                    $new_idom = $self->_intersect(\%dom, $pred_id, $new_idom);
   206→                }
   207→
   208→                # Update if changed
   209→                if (not(exists($dom{$node_id}))) {
   210→                    $dom{$node_id} = $new_idom;
   211→                    $changed = 1;
   212→                }
   213→                elsif ($dom{$node_id} ne $new_idom) {
   214→                    $dom{$node_id} = $new_idom;
   215→                    $changed = 1;
   216→                }
   217→            }
   218→        }
   219→
   220→        return \%dom;
   221→    }
   222→
   223→    # Helper: Find intersection of two nodes in dominance tree
   224→    method _intersect($dom, $b1, $b2) {
   225→        my $finger1 = $b1;
   226→        my $finger2 = $b2;
   227→
   228→        while ($finger1 ne $finger2) {
   229→            # Move up dominance tree
   230→            while ($self->_node_depth($finger1) > $self->_node_depth($finger2)) {
   231→                $finger1 = $dom->{$finger1};
   232→                last unless defined($finger1);
   233→            }
   234→            last unless defined($finger1);
   235→
   236→            while ($self->_node_depth($finger2) > $self->_node_depth($finger1)) {
   237→                $finger2 = $dom->{$finger2};
   238→                last unless defined($finger2);
   239→            }
   240→            last unless defined($finger2);
   241→
   242→            if ($finger1 eq $finger2) {
   243→                last;
   244→            }
   245→
   246→            # Both at same depth, move up together
   247→            $finger1 = $dom->{$finger1};
   248→            $finger2 = $dom->{$finger2};
   249→
   250→            last unless defined($finger1);
   251→            last unless defined($finger2);
   252→        }
   253→
   254→        return $finger1;
   255→    }
   256→
   257→    # Helper: Get node depth from node_id (simple heuristic: parse number)
   258→    method _node_depth($node_id) {
   259→        return 0 unless defined($node_id);
   260→        if ($node_id =~ /node_(\d+)/) {
   261→            return $1;
   262→        }
   263→        return 0;
   264→    }
   265→
   266→    # Validate dominance property: definitions dominate uses
   267→    method validate_dominance($graph) {
   268→        my @errors = ();
   269→
   270→        my $dom_tree = $self->compute_dominance_tree($graph);
   271→        my $nodes = $graph->nodes;
   272→
   273→        # Check each Load node: its Store must exist and be valid
   274→        for my $node_id (keys $nodes->%*) {
   275→            my $node = $nodes->{$node_id};
   276→            if ($node->op eq 'Load') {
   277→                my $var_name = $node->attributes->{variable};
   278→                my $store_id = $node->attributes->{store_id};
   279→
   280→                if (defined($store_id)) {
   281→                    if (defined($var_name)) {
   282→                        # Check if store exists
   283→                        if (not(exists($nodes->{$store_id}))) {
   284→                            push @errors, "Dominance violation: Load of $var_name in $node_id references non-existent Store $store_id";
   285→                            next;
   286→                        }
   287→
   288→                        my $store_node = $nodes->{$store_id};
   289→                        if ($store_node->op ne 'Store') {
   290→                            push @errors, "Dominance violation: Load of $var_name in $node_id references $store_id which is not a Store node";
   291→                            next;
   292→                        }
   293→
   294→                        # For graphs with control flow (Region nodes), check strict dominance
   295→                        # For linear graphs (Chapters 1-4), the store_id reference is sufficient
   296→                        my $has_control_flow = $self->_has_control_flow($graph);
   297→
   298→                        if ($has_control_flow) {
   299→                            my $is_dominated = $self->_dominates($dom_tree, $store_id, $node_id);
   300→                            if (not($is_dominated)) {
   301→                                push @errors, "Dominance violation: Load of $var_name in $node_id is not dominated by its Store in $store_id";
   302→                            }
   303→                        }
   304→                    }
   305→                }
   306→            }
   307→        }
   308→
   309→        return @errors;
   310→    }
   311→
   312→    # Helper: Check if graph has control flow (Region/If nodes)
   313→    method _has_control_flow($graph) {
   314→        my $nodes = $graph->nodes;
   315→        for my $node_id (keys $nodes->%*) {
   316→            my $node = $nodes->{$node_id};
   317→            if ($node->op eq 'Region' || $node->op eq 'If') {
   318→                return 1;
   319→            }
   320→        }
   321→        return 0;
   322→    }
   323→
   324→    # Helper: Check if dominator_id dominates target_id
   325→    method _dominates($dom_tree, $dominator_id, $target_id) {
   326→        return 1 if $dominator_id eq $target_id;
   327→
   328→        # Walk up dominance tree from target
   329→        my $current = $target_id;
   330→        my $max_steps = 100;
   331→        my $steps = 0;
   332→
   333→        while (defined($current)) {
   334→            if ($steps > $max_steps) {
   335→                last;
   336→            }
   337→            $steps++;
   338→
   339→            if (exists($dom_tree->{$current})) {
   340→                $current = $dom_tree->{$current};
   341→                if (defined($current)) {
   342→                    if ($current eq $dominator_id) {
   343→                        return 1;
   344→                    }
   345→                }
   346→            }
   347→            else {
   348→                last;
   349→            }
   350→        }
   351→
   352→        return 0;
   353→    }
   354→
   355→    # Validate phi node placement (prepare for Chapter 5)
   356→    method validate_phi_placement($graph) {
   357→        my @errors = ();
   358→
   359→        my $nodes = $graph->nodes;
   360→
   361→        # Check each Phi node
   362→        for my $node_id (keys $nodes->%*) {
   363→            my $node = $nodes->{$node_id};
   364→            next unless $node->op eq 'Phi';
   365→
   366→            # Phi must be at a Region (control flow merge point)
   367→            my $phi_inputs = $node->inputs;
   368→            if (scalar($phi_inputs->@*) == 0) {
   369→                push @errors, "Phi node $node_id has no control input (must connect to Region)";
   370→                next;
   371→            }
   372→
   373→            my $region_id = $phi_inputs->[0];
   374→            if (exists($nodes->{$region_id})) {
   375→                my $region_node = $nodes->{$region_id};
   376→                if ($region_node->op ne 'Region' && $region_node->op ne 'Loop') {
   377→                    push @errors, "Phi node $node_id is not at a Region/Loop merge point (control input is " . $region_node->op . ")";
   378→                }
   379→                else {
   380→                    # Count region/loop predecessors
   381→                    my $region_preds = $region_node->inputs;
   382→                    my $expected_alternatives = scalar($region_preds->@*);
   383→
   384→                    # Count phi alternatives from inputs array (first input is control, rest are values)
   385→                    my $phi_inputs = $node->inputs;
   386→                    my $actual_alternatives = scalar($phi_inputs->@*) - 1;  # Subtract control input
   387→
   388→                    if ($actual_alternatives != $expected_alternatives) {
   389→                        push @errors, "Phi node $node_id in node $region_id expects $expected_alternatives value inputs ($expected_alternatives predecessors) but has $actual_alternatives";
   390→                    }
   391→                }
   392→            }
   393→            else {
   394→                push @errors, "Phi node $node_id references non-existent Region $region_id";
   395→            }
   396→        }
   397→
   398→        return @errors;
   399→    }
   400→}
   401→
   402→1;
   403→
   404→=pod
   405→
   406→=head1 NAME
   407→
   408→Chalk::IR::Validator - Comprehensive validation for Sea of Nodes IR graphs
   409→
   410→=head1 SYNOPSIS
   411→
   412→    use Chalk::IR::Validator;
   413→    use Chalk::IR::Graph;
   414→
   415→    my $graph = Chalk::IR::Graph->new();
   416→    # ... build graph ...
   417→
   418→    my $validator = Chalk::IR::Validator->new();
   419→    my ($success, $errors) = $validator->validate_all($graph);
   420→
   421→    if (!$success) {
   422→        for my $error (@$errors) {
   423→            warn "Validation error: $error\n";
   424→        }
   425→    }
   426→
   427→=head1 DESCRIPTION
   428→
   429→Chalk::IR::Validator provides comprehensive validation infrastructure for Sea of Nodes
   430→IR graphs. It checks critical properties required for correct compilation:
   431→
   432→=over 4
   433→
   434→=item * B<CFG Structure> - Single Start node, at least one Return node, all nodes reachable
   435→
   436→=item * B<SSA Form> - Each variable assigned exactly once (Static Single Assignment)
   437→
   438→=item * B<Dominance> - Variable uses dominated by their definitions
   439→
   440→=item * B<Phi Placement> - Phi nodes only at control flow merge points with correct arity
   441→
   442→=back
   443→
   444→This validator is designed to catch IR construction errors immediately, before they
   445→cause subtle bugs in later compilation phases.
   446→
   447→=head1 METHODS
   448→
   449→=head2 validate_all($graph)
   450→
   451→Main entry point. Runs all validators and returns results.
   452→
   453→    my ($success, $errors) = $validator->validate_all($graph);
   454→
   455→Returns:
   456→
   457→=over 4
   458→
   459→=item * C<$success> - Boolean: 1 if all validations pass, 0 if any fail
   460→
   461→=item * C<$errors> - ArrayRef of error message strings
   462→
   463→=back
   464→
   465→=head2 validate_cfg($graph)
   466→
   467→Validates Control Flow Graph structure:
   468→
   469→=over 4
   470→
   471→=item * Exactly one Start node exists
   472→
   473→=item * At least one Return node exists
   474→
   475→=item * All nodes are reachable from Start (no orphaned nodes)
   476→
   477→=back
   478→
   479→Returns: List of error messages (empty if valid)
   480→
   481→=head2 validate_single_assignment($graph)
   482→
   483→Validates SSA (Static Single Assignment) property:
   484→
   485→=over 4
   486→
   487→=item * Each variable (Store node) is assigned exactly once
   488→
   489→=back
   490→
   491→In SSA form, multiple assignments to the same variable name are prohibited.
   492→Use phi nodes at control flow merge points instead.
   493→
   494→Returns: List of error messages (empty if valid)
   495→
   496→=head2 compute_dominance_tree($graph)
   497→
   498→Computes the dominance tree using Cooper/Harvey/Kennedy algorithm.
   499→
   500→Returns: HashRef mapping C<node_id =E<gt> immediate_dominator_id>
   501→
   502→A node A dominates node B if every path from Start to B passes through A.
   503→The immediate dominator is the closest dominator (excluding the node itself).
   504→
   505→=head2 validate_dominance($graph)
   506→
   507→Validates dominance property:
   508→
   509→=over 4
   510→
   511→=item * Each variable use (Load node) is dominated by its definition (Store node)
   512→
   513→=back
   514→
   515→This ensures variables are defined before use in all possible execution paths.
   516→
   517→Returns: List of error messages (empty if valid)
   518→
   519→=head2 validate_phi_placement($graph)
   520→
   521→Validates phi node placement (Chapter 5 prerequisite):
   522→
   523→=over 4
   524→
   525→=item * Phi nodes only appear at Region (control flow merge) nodes
   526→
   527→=item * Number of phi alternatives matches number of control predecessors
   528→
   529→=item * Each phi input corresponds to an incoming control edge
